with with_windows as (select id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, firmware, row_number() over w_hist as event_seq, round(humidity / sum(humidity) over (partition by device_code), 4) as humidity_share, lead(status_bits, 2) over w_grp as next_status_bits from device_readings window w_hist as (order by status_bits desc, id), w_grp as (order by status_bits, id)) select date_trunc('hour', reading_ts) as hour_window, (unix_timestamp(max(reading_ts)) - unix_timestamp(min(reading_ts))) / 60 as span_minutes, sort_array(collect_set(device_code)) as device_code_list, size(collect_set(device_code)) as num_device_codes, count(*) filter (where device_code = 'DV-03') as dv_03_rows from with_windows group by 1 order by span_minutes desc;
